// todo resource: JSON API over /todos with full CRUD - list, get by id,
// create, update by id, delete by id - with todos addressed by integer
// primary key.
//
// A todo has a title and a completed flag, and nothing else of its own.

const todos = [
  {
    "id": 1,
    "title": "Complete my favorite book",
    "completed": true
  },
  {
    "id": 2,
    "title": "Review current project",
    "completed": false
  }
];

// Add the todo resource to endpoints and validate
function addTodo(title, completed) {
  todos.push({ "id":todos.length+1,"title":title,"completed":completed });
}

// CRUD operations to add, retrieve, update, and delete
function listAllTodos() {
  return todos;
}

// CRUD operations to get by id, create, update, and delete
function getTodoById(id) {
  return todos.find(todo => todo.id === id);
}

// CRUD operations to create
function addTodoById(id, title) {
  const todo = { "id": id, "title": title, "completed": false };
  todos.push(todo);
}

// CRUD operations to update
function updateTodoById(id, title) {
  const todo = todos.find(todo => todo.id === id);
  if (!todo) return null;

  // Update completed flag
  todo.completed = title === "true";
}

// CRUD operations to delete
function deleteTodoById(id) {
  todos = todo.filter(todo => todo.id !== id);
}

// Define a function to handle CRUD operations
function manageTodoOperations(id) {
  const todo = todos.find(todo => todo.id === id);

  switch (todo?.completed) {
    case true:
      // Complete a todo
      updateTodoById(id, "true");
      break;
    case false:
      // Uncomplete a todo
      updateTodoById(id, "false");
      break;
    default:
      // Set completed flag using PUT
      addTodoById(id, "true");
  }
}

// Example usage:
manageTodoOperations(2); // Update completed flag for todo with id 2
